EBOOKS : [
  { id:"eb1", title:"Peta Lima Elemen PAI", emoji:"📘", pages:[
    { h:"Al-Qur’an Hadis", t:"Al-Qur’an adalah wahyu Allah yang menjadi petunjuk utama; hadis menjelaskan dan merinci maknanya.\n\nCara belajar: baca terjemah, kenali konteks turunnya, lalu cari penerapannya dalam kehidupan sehari-hari.\n\nContoh: Q.S. al-Baqarah/2:148 tentang fastabiqul khairat; Q.S. al-Ḥujurāt/49:6 tentang tabayyun." },
    { h:"Akidah", t:"Akidah adalah keyakinan pokok: iman kepada Allah, malaikat, kitab, rasul, hari akhir, dan takdir.\n\nSyu‘ab al-īmān menunjukkan bahwa iman mencakup keyakinan, ucapan, dan perbuatan.\n\nAkidah yang benar melahirkan akhlak dan amal yang sehat." },
    { h:"Akhlak", t:"Akhlak adalah kualitas perilaku yang lahir dari hati yang bersih.\n\nPenyakit hati seperti hasad, takabur, ujub, dan riya merusak akhlak. Obatnya: taubat, muhasabah, syukur, sabar, ikhlas, dan silaturahmi.\n\nAkhlak digital juga termasuk: tabayyun, menjaga privasi, dan menolak cyberbullying." },
    { h:"Fikih", t:"Fikih membahas hukum amal mukalaf berdasarkan dalil.\n\nSumbernya: Al-Qur’an, Sunnah, ijma’, dan qiyas; ijtihad digunakan untuk kasus baru.\n\nPrinsip maqāṣid menjaga agama, jiwa, akal, keturunan, dan harta. Perbedaan pendapat ulama disikapi dengan adab." },
    { h:"Sejarah Peradaban Islam", t:"Islam masuk Nusantara melalui perdagangan, dakwah, perkawinan, pendidikan, dan akulturasi.\n\nTernate dan Tidore menjadi pusat Islam Maluku; Wali Songo berdakwah di Jawa dengan pendekatan budaya.\n\nBelajar sejarah melatih kritik sumber dan refleksi untuk masa kini." } ] },
  { id:"eb2", title:"Fastabiqul Khairat & Iman", emoji:"📗", pages:[
    { h:"Berlomba dalam Kebaikan", t:"Fastabiqul khairat berarti bersegera dan berlomba dalam kebaikan, bukan berlomba dalam popularitas.\n\nKuncinya: niat ikhlas, ilmu yang benar, dan konsistensi.\n\nAmal kecil yang rutin lebih baik daripada amal besar yang hanya sekali." },
    { h:"Cabang-Cabang Iman", t:"Syu‘ab al-īmān mencakup keyakinan hati, ucapan lisan, dan perbuatan anggota badan.\n\nContoh: tauhid, jujur, amanah, malu berbuat dosa, menolong, dan menjaga kebersihan.\n\nIman yang benar terlihat dalam perilaku sehari-hari, termasuk di media sosial." },
    { h:"Hati yang Sehat", t:"Penyakit hati perlu dikenali sebelum diobati.\n\nLangkahnya: sadar, berhenti, bertobat, muhasabah, mengganti kebiasaan, dan menjaga konsistensi.\n\nZikir, syukur, sabar, dan silaturahmi membantu hati kembali tenang." },
    { h:"Adab Digital", t:"Sebelum mengunggah atau membagikan: periksa kebenaran, jaga privasi, dan pikirkan dampaknya.\n\nJangan menyebarkan hoaks, ujaran kebencian, atau komentar yang menyakiti.\n\nJejak digital adalah amal yang bisa menjadi saksi di kemudian hari." } ] },
  { id:"eb3", title:"Jejak Islam Nusantara", emoji:"📙", pages:[
    { h:"Teori & Bukti", t:"Teori Gujarat, Persia, Arab, dan Cina masing-masing memiliki pendukung dan bukti.\n\nBukti awal: Samudera Pasai, catatan Marco Polo (1292), Ibn Battuta (1345), makam, prasasti, dan tradisi lokal.\n\nSejarawan membaca bukti secara kritis, bukan memilih teori karena popularitas." },
    { h:"Wali Songo & Ulama", t:"Wali Songo berdakwah di Jawa melalui wayang, tembang, pesantren, dan perdagangan.\n\nUlama Nusantara lain: Hamzah Fansuri, Abdurrauf as-Singkili, Sheikh Yusuf al-Makassari.\n\nWarisan mereka: pendidikan, karya tulis, dan tradisi keilmuan." },
    { h:"Maluku & Rempah", t:"Cengkih dan pala menghubungkan Maluku dengan jaringan dagang dunia.\n\nTernate dan Tidore menjadi kesultanan Islam; Sultan Zainal Abidin, Hairun, dan Baabullah meninggalkan jejak penting.\n\nBaabullah membebaskan Ternate dari Portugis pada 1575." },
    { h:"Proyek Jejak Islam", t:"Langkah proyek: pilih objek, rumuskan pertanyaan, kumpulkan sumber, kritik sumber, dan sajikan temuan.\n\nJaga etika: minta izin, hormati privasi, dan sebutkan sumber.\n\nHubungkan temuan dengan lima elemen PAI dan refleksikan maknanya bagi kehidupanmu." } ] }
],

